// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner, address caller) public {
        // The owner starts as address(0); make `caller` the owner first (valid for any caller).
        vm.prank(address(0));
        c.transferOwnership(caller);

        vm.assume(newOwner != caller); // inputs where P and M must agree: owner becomes newOwner

        vm.prank(caller);
        c.transferOwnership(newOwner);

        // General rule: after a successful transferOwnership(newOwner), c.owner() == newOwner.
        assertTrue(c.owner() == newOwner);
    }
}

