contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address a, address b) public {
        vm.assume(a != b);
        address current = c.owner();

        // current owner legitimately transfers ownership to a
        vm.prank(current);
        c.transferOwnership(a);

        // the previous owner must no longer be able to transfer ownership
        vm.prank(current);
        try c.transferOwnership(b) {
            // mutated contract lets the stale owner take over
        } catch {
            // reference contract reverts here
        }

        // ownership must still be exactly what the legitimate transfer set
        assertTrue(c.owner() == a);
    }
}

