pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        // Admissible domain: the initial owner is address(0); the account that
        // will later invoke owned() must first be made the current owner via
        // the legitimate ownership-transfer entry point, and must be a
        // meaningful address. This keeps the domain wide (any actor, any
        // successor) while ensuring owned() succeeds rather than reverting on
        // the reference.
        vm.assume(actor != address(0));

        // Legitimately transfer ownership to `actor` (the initial owner is
        // address(0), which is the only account for which onlyOwner passes).
        vm.prank(address(0));
        c.transferOwnership(actor);

        // Snapshot the owner installed by transferOwnership.
        address ownerBefore = c.owner();

        // Drive c through `owned` as the current owner (admissible caller).
        vm.prank(actor);
        bool ok;
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: a call to owned() never changes the owner; the owner remains
        // exactly the address installed by transferOwnership. The buggy
        // version overwrites owner with msg.sender inside owned(), so the
        // owner diverges from the transferOwnership-installed value.
        assertTrue(c.owner() == ownerBefore, "owner must be unchanged by owned()");
    }
}

