pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner, address caller) public {
        // WIDE domain: both addresses are fully fuzzed; the interesting case is
        // caller != newOwner (owned() must not be able to rewrite the installed owner)
        // and caller == newOwner (owned() must be a state-preserving no-op).
        vm.assume(newOwner != address(0) || caller != address(0));

        // Install an explicit owner: only address(0) (the initial owner) can do this.
        vm.prank(address(0));
        c.transferOwnership(newOwner);
        require(c.owner() == newOwner);

        // Drive c through `owned` from an arbitrary fuzzed caller.
        vm.prank(caller);
        try c.owned() {
            // even when the call succeeds (caller == owner), owner must be unchanged
        } catch {
            // non-owner calls revert; owner must still be unchanged
        }

        // The single general rule: after owned(), owner is still exactly the
        // address installed via transferOwnership, for EVERY caller.
        assertTrue(c.owner() == newOwner);
    }
}

